mapper.select:
select t.*, (select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scvb.value = t.document_type and scb.code = 'CON.RATE_DOCUMENT_TYPE' and scb.enabled_flag = 'Y' and scvb.enabled_flag = 'Y')AS document_type_n, (select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code_id = scvb.code_id and scvb.value = t.status and scb.code = 'HLS_WFL_STATUS' and scb.enabled_flag = 'Y' and scvb.enabled_flag = 'Y')AS status_n, nvl((select sum(nvl(l.interest_adj_amount,0)) from con_floating_rate_req_ln l where l.flt_req_id = t.flt_req_id),0) total_interest_adj_amount from con_floating_rate_req t
1=1
and t.flt_req_date = #{fltReqDate}
and t.status = #{status}
and t.flt_req_number like concat(CONCAT('%',#{fltReqNumber}),'%')
and t.flt_req_id =#{fltReqId}
order by t.flt_req_date desc

SELECT cfrr.*, ( SELECT scvb.MEANING FROM sys_code_value_b scvb WHERE code_id = ( SELECT code_id FROM sys_code_b WHERE CODE = 'CON.CONTRACT_PROCESS_STATUS' ) AND scvb.VALUE= cfrr. STATUS ) AS statusDesc, (select hdt.description from hls_document_type hdt where hdt.document_category = 'CON_FLOATING_RATE_REQ' and hdt.document_type = cfrr.document_type) document_type_desc, (select fbrs.valid_from from fnd_base_rate_set fbrs where fbrs.base_rate_set = cfrr.base_rate_set) valid_from FROM con_floating_rate_req cfrr
flt_req_id = #{fltReqId}
and company_id = #{companyId}
AND status IN
#{item}

select base_rate_set,valid_from from fnd_base_rate_set

    1=1

        and base_rate_set = #{baseRateSet}


        and valid_from = #{validFrom}
